ナナメ読みする';c.before(d);var e=!1;d.addEventListener('click',function(){var f=d.querySelector('.btn-text');if(!e){c.style.transform='rotate(-4deg)';c.style.transition='transform .3s ease';c.style.transformOrigin='top center';d.classList.add('is-active');f.innerHTML='ナナメ読みをやめる';e=!0}else{c.style.transform='rotate(0deg)';d.classList.remove('is-active');f.innerHTML='ナナメ読みする';e=!1}})})})();

